 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--enable-unsafe-swiftshader']);page=b.new_page(viewport={'width':390,'height':844});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(os.environ.get('JACKPOT_QA_URL','http://127.0.0.1:3400')+'/?bonus=jackpot');page.get_by_role('button',name='チャレンジ開始',exact=True).click();page.get_by_role('button',name='1球発射',exact=True).click();expect(page.locator('.abyss-focus-label')).to_contain_text('1段目クルーン / 自動拡大',timeout=30000);page.get_by_role('button',name='一時停止',exact=True).click();page.get_by_role('button',name='全体',exact=True).click();expect(page.locator('.abyss-overview-label')).to_be_hidden();page.get_by_role('button',name='皿2',exact=True).focus();page.keyboard.press('Enter');expect(page.locator('.abyss-focus-label')).to_contain_text('2段目クルーン / 拡大表示');page.evaluate("document.querySelectorAll('details').forEach(d=>d.open=true)");page.get_by_label('動き・点滅を減らす',exact=True).check();expect(page.locator('.abyss-focus-label')).to_contain_text('2段目クルーン');page.get_by_role('button',name='自動拡大',exact=True).click();expect(page.locator('.abyss-overview-label')).to_be_hidden();assert not errors,errors;Path('docs/qa/jackpot-camera/ui-report.json').write_text(json.dumps({'normalLaunchAutomaticZoom':True,'manualKeyboardViews':True,'reducedMotion':True,'errors':errors},indent=2));print('UI passed',errors);b.close()
